custom_css:
/* ==========================================================================
   SC Bordeaux · 柔焦体积玻璃版 (v3.16 · Mobile Flex & Cascade Cleanup)
   架构与视觉同构（对齐 SillyClient 前端 styles.css + UI-UX-BASELINE）：
   1. 手机端/移动端防遮挡弹性底栏（Flex 岛屿上下结构，彻底杜绝输入框骑在对话上）：
      - #sheld 设为真正的垂直 Flex 容器，垂直容纳 #chat 与 #form_sheld，以 10px 间距物理隔离；
      - #chat 占据上方全部可用空间并独立内滚 (flex: 1 1 0px; min-height: 0;)，消息永远在输入框上方结束；
      - #form_sheld 恢复为流式弹性子项 (flex: 0 0 auto; relative;)，高度自适应撑开，绝不遮挡最后一条消息；
   2. 主抽屉即时显隐与二级手风琴原生滑动：
      - 主抽屉高度随内容自适应，并限制在可视区域内；玻璃模糊只放在外层面板；
      - 主抽屉开关不追加高度、透明度、缩放或滤镜过渡；二级抽屉保留原生 slideToggle；
      - 二级抽屉材质不随开关切换，内容的高度与上下内边距交给原生动画同步收回；
   3. 动效套件：保留酒馆原生二级抽屉滑动，并只为实际使用的弹层声明入口动效；
   4. 通透酒红液态玻璃材质 + 中心实、四周羽化渐隐的无框体积感；
   5. 顶栏纯净无底框 Tab + 适度小圆角 (14px) + 纯图标亮度/光晕状态切换；
   6. 滑块与开关 1:1 复刻 SillyClient 前端样式 (.ios-font-slider + .companion-preset__switch)。
   ========================================================================== */

/* ---------- 1. 核心设计令牌、圆润字体、圆角收敛与中心-四周渐隐体积引擎 ---------- */
:root {
  --ft-theme-active: 1;

  /* 头像与背景环境微调令牌 */
  --sc-bg-blur: var(--ftu-bg-blur, 14px);
  --sc-mes-avatar-size: 32px;

  /* SC Bordeaux 品牌核心色板（暗夜酒红 #a32848 × 柔光玫瑰 #da7694 × 黑曜石深底） */
  --sc-accent-rgb: 163, 40, 72;
  --sc-rose-rgb: 218, 118, 148;
  --sc-accent-fg: rgba(255, 250, 252, 0.96);
  --sc-surface-rgb: 26, 10, 18;
  --sc-dim-rgb: 16, 6, 11;
  --sc-solid-rgb: 11, 4, 8;

  /* 可调几何与排版参数 */
  --ft-gap: var(--ftu-gap, 10px);
  --ft-mes-pad: var(--ftu-mes-pad, 22px);
  --ft-density: var(--ftu-density, 1);
  --ft-roundness: var(--ftu-roundness, 1);
  --lh-body: var(--ftu-line-height, 1.8);
  --ft-para-gap: var(--ftu-para-gap, 0.78em);
  --ft-letter-spacing: var(--ftu-letter-spacing, 0.1px);
  --ft-saturate: var(--ftu-saturate, 140%);
  --ft-motion: var(--ftu-motion, 1);
  --ft-toast-offset: var(--ftu-toast-offset, 0px);
  --ft-toast-lines: var(--ftu-toast-lines, 4);

  /* 圆润字体栈：接管上游 --mainFontFamily，融合苹果圆体 / 鸿蒙 / 小米兰亭圆润黑体 / 幼圆 / 苹方 */
  --ft-font-family: var(
    --ftu-font-family,
    ui-rounded,
    "SF Pro Rounded",
    "PingFang SC",
    "HarmonyOS Sans SC",
    "MiSans",
    "Segoe UI",
    "Microsoft YaHei UI",
    "Microsoft YaHei",
    system-ui,
    -apple-system,
    sans-serif
  );
  --mainFontFamily: var(--ft-font-family) !important;

  /* 4px 栅格间距体系 */
  --sp-1: calc(4px * var(--ft-density));
  --sp-2: calc(8px * var(--ft-density));
  --sp-3: calc(12px * var(--ft-density));
  --sp-4: calc(16px * var(--ft-density));
  --sp-5: calc(20px * var(--ft-density));
  --sp-6: calc(24px * var(--ft-density));
  --sp-8: calc(32px * var(--ft-density));

  /* 适度收敛的圆角体系（顶栏 14px / 内部 Tab 10px / 控件 12px / 卡片 16-20px / 大面板 24px） */
  --r-xs: calc(8px * var(--ft-roundness));
  --r-tab: calc(10px * var(--ft-roundness));
  --r-sm: calc(12px * var(--ft-roundness));
  --r-topbar: calc(14px * var(--ft-roundness));
  --r-md: calc(16px * var(--ft-roundness));
  --r-lg: calc(20px * var(--ft-roundness));
  --r-xl: calc(24px * var(--ft-roundness));
  --r-pill: 9999px;

  /* 字号、行高与标准触控高度 */
  --fs-xs: calc(var(--mainFontSize) * 0.76);
  --fs-sm: calc(var(--mainFontSize) * 0.875);
  --fs-md: var(--mainFontSize);
  --fs-lg: calc(var(--mainFontSize) * 1.12);
  --fs-xl: calc(var(--mainFontSize) * 1.26);
  --lh-tight: 1.38;
  --lh-ui: 1.52;
  --ft-ctl-h: max(34px, calc(var(--mainFontSize) * 2.05));
  --ft-icon-btn: max(34px, calc(var(--mainFontSize) * 2.08));

  /* 动效曲线（对齐 SillyClient 前端 styles.css:103-118） */
  --motion-press: calc(80ms * var(--ft-motion));
  --motion-release: calc(150ms * var(--ft-motion));
  --dur-1: calc(140ms * var(--ft-motion));
  --dur-2: calc(220ms * var(--ft-motion));
  --dur-3: calc(320ms * var(--ft-motion));
  --motion-ease-press: cubic-bezier(0.2, 0, 0, 1);
  --motion-ease-release: cubic-bezier(0.16, 1, 0.3, 1);
  --tgEase: cubic-bezier(0.22, 1, 0.36, 1);
  --tgSpring: cubic-bezier(0.22, 1, 0.36, 1);
  --scFastOut: cubic-bezier(0.16, 1, 0.3, 1);
  --motion-dissolve-ease: cubic-bezier(0.5, 0, 0.2, 1);
  --ease: var(--tgSpring);
  --ease-spring: cubic-bezier(0.22, 1, 0.36, 1);

  /* 动态派生语义颜色（彻底归零默认细边框色 --c-line） */
  --c-1: rgb(var(--sc-accent-rgb));
  --c-2: var(--SmartThemeUnderlineColor, rgb(var(--sc-rose-rgb)));
  --c-text: var(--SmartThemeBodyColor, rgba(246, 241, 243, 0.94));
  --c-text-2: var(--SmartThemeEmColor, rgb(var(--sc-rose-rgb)));
  --c-text-3: color-mix(in srgb, var(--c-text) 54%, transparent);
  --c-line: transparent;
  --c-line-strong: transparent;
  --c-danger: #e05260;
  --c-success: #34c759;
  --c-warning: #e8a534;

  --fill-1: rgba(255, 232, 240, 0.045);
  --fill-2: rgba(255, 232, 240, 0.075);
  --fill-3: rgba(255, 232, 240, 0.115);
  --accent-soft: color-mix(in srgb, var(--c-1) 24%, transparent);
  --accent-ring: color-mix(in srgb, var(--c-1) 28%, transparent);
  --gradient-main: linear-gradient(135deg, var(--c-1) 0%, color-mix(in srgb, var(--c-1) 48%, var(--c-2)) 55%, var(--c-2) 100%);

  /* 通透四级暗夜酒红玻璃材质（恢复通透度：主面板 0.55 / 聊天 0.34 / 浮层 0.55 / 顶层 0.82） */
  --glass-panel: rgb(from var(--SmartThemeBlurTintColor) r g b / var(--ftu-panel-alpha, min(0.55, alpha)));
  --glass-chat: rgb(from var(--SmartThemeChatTintColor) r g b / var(--ftu-chat-alpha, min(0.34, alpha)));
  --glass-float: rgb(from var(--SmartThemeBlurTintColor) r g b / var(--ftu-panel-alpha, min(0.55, alpha)));
  --glass-top: rgb(from var(--SmartThemeBlurTintColor) r g b / max(0.82, var(--ftu-panel-alpha, alpha)));
  --glass-blur: blur(var(--SmartThemeBlurStrength)) saturate(var(--ft-saturate));

  /* =======================================================================
     真正的「中心微醇、四周向边缘柔和渐隐消散」通透梯度体系（无细线边框、保持玻璃呼吸感）
     ======================================================================= */

  /* 大面板顶部固定高度柔焦光洗（100% 220px，展开抽屉时绝不随高度拉伸重绘） */
  --vol-panel-wash:
    radial-gradient(ellipse 75% 180px at 50% 0%, rgba(163, 40, 72, 0.08) 0%, rgba(218, 118, 148, 0.025) 55%, transparent 100%),
    linear-gradient(180deg, rgba(255, 225, 236, 0.025) 0%, transparent 140px);

  /* AI 消息卡：中心通透柔焦 (0.42) -> 四周边缘柔和羽化 (0.16) */
  --vol-card-bot-bg:
    radial-gradient(ellipse 115% 110% at 50% 45%, rgba(30, 12, 21, 0.42) 0%, rgba(26, 10, 18, 0.30) 62%, rgba(20, 7, 14, 0.16) 100%);

  /* 用户消息卡：中心通透酒红 (0.34) -> 四周边缘柔和羽化 (0.12) */
  --vol-card-user-bg:
    radial-gradient(ellipse 115% 110% at 50% 45%, rgba(116, 26, 52, 0.34) 0%, rgba(92, 20, 42, 0.24) 62%, rgba(64, 14, 30, 0.12) 100%);

  /* 内部控件（手风琴标题栏 / 按钮 / 列表项）：中心微亮 (0.068) -> 四周渐隐消散 (0.012) */
  --vol-surface-bg:
    radial-gradient(ellipse 120% 115% at 50% 50%, rgba(255, 230, 240, 0.068) 0%, rgba(255, 230, 240, 0.042) 62%, rgba(255, 230, 240, 0.012) 100%);

  /* 内部控件悬停：中心酒红微暖 (0.24) -> 四周渐隐消散 (0.04) */
  --vol-surface-hover-bg:
    radial-gradient(ellipse 120% 115% at 50% 50%, rgba(var(--sc-accent-rgb), 0.24) 0%, rgba(var(--sc-accent-rgb), 0.14) 62%, rgba(var(--sc-accent-rgb), 0.04) 100%);

  /* 凹槽（输入框 / 下拉框 / 展开内胆）：中心深邃 (0.34) -> 四周柔和过渡 (0.12) */
  --vol-recess-bg:
    radial-gradient(ellipse 120% 115% at 50% 50%, rgba(4, 1, 3, 0.34) 0%, rgba(8, 3, 6, 0.22) 65%, rgba(14, 5, 10, 0.12) 100%);

  /* =======================================================================
     纯净外部景深阴影（对齐 SillyClient styles.css .manage-panel-surface，
     彻底移除所有发亮 inset 内框线，只用柔和外阴影与凹凸明暗表达层级）
     ======================================================================= */
  --shadow-c: rgba(4, 1, 3, calc(0.38 * var(--ftu-shadow, 1)));
  --shadow-c-half: rgba(4, 1, 3, calc(0.18 * var(--ftu-shadow, 1)));

  /* 面板级外阴影（无发光内边） */
  --elev-1:
    0 6px 18px -4px var(--shadow-c-half),
    0 2px 6px -1px rgba(4, 1, 3, 0.12);
  --elev-2:
    0 14px 32px -6px var(--shadow-c),
    0 3px 10px -2px rgba(4, 1, 3, 0.14);
  --elev-3:
    0 18px 42px -6px var(--shadow-c),
    0 4px 12px -2px rgba(4, 1, 3, 0.18);
  --elev-4:
    0 24px 56px -8px rgba(4, 1, 3, 0.52),
    0 6px 16px -3px rgba(4, 1, 3, 0.24);

  /* 消息卡片柔和体积阴影（零发光内框） */
  --vol-card-shadow:
    0 10px 26px -6px rgba(4, 1, 3, 0.26),
    0 2px 6px -1px rgba(4, 1, 3, 0.12);

  /* 内部控件极轻体积感（对齐 UI-UX-BASELINE：未选中控件只保留极弱外部体积感，不泛用内发光） */
  --vol-ctl-shadow:
    0 3px 10px -3px rgba(0, 0, 0, 0.16);

  /* 输入槽位柔和内凹阴影（对齐 SillyClient .manage-recess：仅顶部极轻内暗影，无底部白边） */
  --vol-recess-shadow:
    inset 0 1.5px 3.5px rgba(0, 0, 0, 0.26);

  /* SillyTavern 原生变量桥接：启用 200ms/280ms 原生物理流畅展开动画引擎 */
  --icon-size: var(--mainFontSize);
  --scroll-width: 5px;
  --animation-duration: 200ms;
  --animation-duration-2x: 280ms;
}

@media (hover: hover) and (pointer: fine) {
  :root {
    --ft-saturate: var(--ftu-saturate, 146%);
  }
}

/* 关闭模糊（Fast UI 模式）时平滑退化为高不透明度丝绒实色面 */
body.no-blur {
  --glass-panel: rgba(var(--sc-surface-rgb), 0.95);
  --glass-chat: rgba(var(--sc-dim-rgb), 0.90);
  --glass-float: rgba(var(--sc-surface-rgb), 0.97);
  --glass-top: rgba(var(--sc-solid-rgb), 0.98);
}

/* ==========================================================================
   2. 玻璃表面、无框控件与抽屉状态
   ========================================================================== */

/* [PERF-1] 彻底拔除逐字形二次光栅化的全局文字阴影 */
#chat,
.drawer-content,
.popup,
#options,
#extensionsMenu {
  text-shadow: none !important;
}

/* 玻璃表面只在可见区域采样；模糊直接切换，不参与开合动画。 */
#top-bar,
#chat,
#send_form,
.drawer-content.openDrawer,
#character_popup,
#completion_prompt_manager_popup,
#floatingPrompt,
#cfgConfig,
#logprobsViewer,
.draggable,
#dialogue_popup,
#select_chat_popup,
#bulk_tag_popup,
#options .options-content,
#extensionsMenu,
.list-group,
.select2-dropdown,
#toast-container > div,
.popup:not(.transparent_dialogue_popup):not(:has(.popper-modal)),
.popup .popper-modal {
  -webkit-backdrop-filter: var(--glass-blur) !important;
  backdrop-filter: var(--glass-blur) !important;
}

body.no-blur #top-bar,
body.no-blur #chat,
body.no-blur #send_form,
body.no-blur .drawer-content.openDrawer,
body.no-blur #character_popup,
body.no-blur #completion_prompt_manager_popup,
body.no-blur #floatingPrompt,
body.no-blur #cfgConfig,
body.no-blur #logprobsViewer,
body.no-blur .draggable,
body.no-blur #dialogue_popup,
body.no-blur #select_chat_popup,
body.no-blur #bulk_tag_popup,
body.no-blur #options .options-content,
body.no-blur #extensionsMenu,
body.no-blur .list-group,
body.no-blur .select2-dropdown,
body.no-blur #toast-container > div,
body.no-blur .popup:not(.transparent_dialogue_popup):not(:has(.popper-modal)),
body.no-blur .popup .popper-modal {
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
}

/* [PERF-2] 全量拔除上游默认 1px 细边框与聚焦线框（彻底消除残余边框感） */
.drawer-content,
.inline-drawer,
.inline-drawer-header,
.inline-drawer-content,
.standoutHeader,
.settingsSectionWrap,
.userSettingsInnerExpandable,
.prompt_order > div,
.range-block-counter input,
.neo-range-input,
.ui-slider,
.ui-widget-content,
.world_entry_form_control,
.mes,
.menu_button,
.text_pole,
.character_select,
.group_select,
.bogus_folder_select,
.recentChat,
.select_chat_block,
.wi-card-entry,
.world_entry,
.avatar,
.avatar img,
.avatar-container.selected,
.tag,
.bg_example,
.popup,
#top-bar,
#send_form,
#options,
#options .options-content,
#extensionsMenu,
#character_popup,
#world_popup,
#completion_prompt_manager_popup,
#completion_prompt_manager_list,
.completion_prompt_manager_prompt,
#floatingPrompt,
#cfgConfig,
#logprobsViewer,
.qr--button,
hr,
.sysHR,
fieldset,
input,
select,
textarea,
button {
  border: none !important;
  outline: none;
}

/* [PERF-3] 二级手风琴抽屉：
   不接管上游 jQuery.slideToggle() 的高度过程，避免主题在展开期间重复参与布局/绘制。
   只固定展开后的表面材质与滚动槽位，保证关闭后不会留下重绘残影。 */
/* .inline-drawer-content: unconstrained for jQuery slideToggle */

.world_entry .inline-drawer:has(> .inline-drawer-header .inline-drawer-icon.up) > .inline-drawer-content {
  padding: 0 !important;
}

/* [PERF-4] 稳定 GPU 合成层与滚动条物理槽位锁定（杜绝抽屉展开撑出滚动条时引发横向挤压） */
#chat {
  contain: layout style;
  isolation: isolate;
  transform: translateZ(0);
  backface-visibility: hidden;
  scrollbar-gutter: stable;
}

.drawer-content {
  contain: layout style;
  scrollbar-gutter: stable;
  animation: none !important;
  transition: none !important;
  will-change: auto !important;
}

/* These wrappers already contain the glass surface; do not sample it again. */
#WorldInfo #world_popup,
#sd_dropdown {
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
}

/* 老式全屏半透遮罩层不叠双层模糊 */
#shadow_popup,
#shadow_character_popup,
#shadow_select_chat_popup,
#bulk_tag_shadow_popup {
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
  background-color: rgba(8, 3, 6, 0.48) !important;
}

/* 二级浮动面板：静态预合成材质，避免开关时重新采样全屏背景 */
#character_popup,
#completion_prompt_manager_popup,
#floatingPrompt,
#cfgConfig,
#logprobsViewer,
.draggable {
  background-color: var(--glass-float) !important;
  background-image: var(--vol-panel-wash) !important;
  background-size: 100% 220px, 100% 140px !important;
  background-repeat: no-repeat !important;
  box-shadow: var(--elev-3) !important;
}

/* .inline-drawer-content: unconstrained for jQuery slideToggle */

.mes {
  contain: layout style;
}

.mes_text {
  contain: layout style;
}

#top-bar,
#send_form {
  transform: translateZ(0);
  backface-visibility: hidden;
}

/* [PERF-5] 视口虚拟化：长列表按需渲染 */
.character_select {
  content-visibility: auto;
  contain-intrinsic-size: auto 72px;
}

.recentChat {
  content-visibility: auto;
  contain-intrinsic-size: auto 58px;
}

.world_entry {
  content-visibility: auto;
  contain-intrinsic-size: auto 64px;
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
  content-visibility: auto;
  contain-intrinsic-size: auto 38px;
}

/* [PERF-6] 全局触控 0ms 响应 */
html,
body,
button,
.menu_button,
.drawer-icon,
.inline-drawer-header,
.mes_button,
.fa-solid.interactable {
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
}

/* ==========================================================================
   3. 圆润字体全局接管与无感滚动条（对齐 SillyClient 前端）
   ========================================================================== */

body,
input,
select,
textarea,
.text_pole,
.mes_text,
.mes_reasoning,
.name_text,
.ch_name,
.popup,
.drawer-content,
.ui-widget,
.select2-container,
button:not(.fa):not(.fas):not(.far):not(.fab):not(.fa-solid):not(.fa-regular):not(.fa-brands),
.menu_button:not(.fa):not(.fas):not(.far):not(.fab):not(.fa-solid):not(.fa-regular):not(.fa-brands) {
  font-family: var(--ft-font-family);
}

body {
  background-color: #1a0a12 !important;
  color: var(--c-text);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

::selection {
  background-color: rgba(var(--sc-accent-rgb), 0.42);
  color: #fff;
}

::-webkit-scrollbar {
  width: var(--scroll-width);
  height: var(--scroll-width);
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb:vertical,
::-webkit-scrollbar-thumb:horizontal {
  background-color: rgba(255, 225, 235, 0.14);
  border-radius: var(--r-pill);
  border: 0;
  box-shadow: none !important;
}

::-webkit-scrollbar-thumb:hover {
  background-color: rgba(var(--sc-rose-rgb), 0.36);
}

::-webkit-scrollbar-thumb:active {
  background-color: rgba(var(--sc-accent-rgb), 0.58);
}

.fa-solid:not(#load-spinner) {
  text-shadow: none !important;
}

.fa-fw:not(#qr--modal-icon):not(#extensionsMenu *):not(#options *):not(.drawer-icon) {
  width: auto;
}

a {
  color: var(--c-2);
  transition: color var(--dur-1) var(--tgEase);
}

/* ==========================================================================
   4. 四级柔焦体积玻璃与全悬浮岛式架构 (Floating Island Layout)
   ========================================================================== */

#dialogue_popup,
#select_chat_popup,
#options .options-content,
#extensionsMenu,
.list-group,
.select2-dropdown,
#toast-container > div {
  border: none !important;
}

body.no-blur .drawer-content,
body.no-blur #character_popup,
body.no-blur #dialogue_popup,
body.no-blur #select_chat_popup,
body.no-blur .draggable,
body.no-blur #options .options-content,
body.no-blur #extensionsMenu,
body.no-blur .list-group,
body.no-blur .select2-dropdown,
body.no-blur #toast-container > div {
  border: none !important;
}

/* 背景柔焦环境模糊：消除背景高频锐利反差，使自适应取色/变色龙色调与半透明玻璃自然交融 */
#bg1,
#bg_custom {
  filter: blur(var(--sc-bg-blur, 14px)) !important;
  transform: scale(1.04) translateZ(0) !important;
  transform-origin: center center !important;
}

body.no-blur #bg1,
body.no-blur #bg_custom {
  filter: none !important;
  transform: none !important;
}

/* L2 抽屉与侧栏玻璃表面：固定高度顶部体积光洗 + 纯外景深阴影（无发光内边） */
.drawer-content,
#dialogue_popup,
#select_chat_popup {
  background-color: var(--glass-panel) !important;
  background-image: var(--vol-panel-wash) !important;
  background-size: 100% 220px, 100% 140px !important;
  background-repeat: no-repeat !important;
  box-shadow: var(--elev-2) !important;
  color: var(--c-text);
}

/* L3 悬浮菜单与下拉面板 */
#options .options-content,
#extensionsMenu,
.list-group,
.select2-dropdown {
  background-color: var(--glass-float) !important;
  background-image: var(--vol-panel-wash) !important;
  background-size: 100% 180px, 100% 120px !important;
  background-repeat: no-repeat !important;
  box-shadow: var(--elev-3) !important;
}

/* L4 模态弹窗本体 */
.popup:not(.transparent_dialogue_popup),
.popup .popper-modal {
  background-color: var(--glass-top) !important;
  background-image: var(--vol-panel-wash) !important;
  background-size: 100% 220px, 100% 140px !important;
  background-repeat: no-repeat !important;
  border: none !important;
  box-shadow: var(--elev-4) !important;
  color: var(--c-text);
}

/* ---------- 4.1 顶栏与纯净图标亮度状态切换 (#top-bar / #top-settings-holder) ----------
   - 顶栏直接贴合屏幕顶部边框 (top: 0)，仅做下半部分圆角 (border-radius: 0 0 var(--r-topbar) var(--r-topbar))；
   - 便于与变色龙自适应取色引擎直接衔接；
   - 彻底去除图标底部的一切圆形/胶囊背景框与阴影 (.drawer-toggle 全状态全透明)；
   - 状态切换纯粹通过图标亮度与光学辉光表达：
     · 未选中 (.closedIcon)：柔和低亮 (opacity 0.42)；
     · 悬停 (:hover)：平滑提亮至 0.86 并泛起微弱暖光；
     · 选中展开 (.openIcon)：100% 亮白珍珠色 + 柔光玫瑰光学辉光 (drop-shadow)。 */
#top-bar,
body.no-blur #top-bar {
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  width: var(--sheldWidth) !important;
  max-width: 100% !important;
  margin: 0 auto !important;
  height: var(--topBarBlockSize) !important;
  border-top: none !important;
  border-top-left-radius: 0 !important;
  border-top-right-radius: 0 !important;
  border-bottom-left-radius: var(--r-topbar) !important;
  border-bottom-right-radius: var(--r-topbar) !important;
  background-color: #1a0a12 !important;
  background-image:
    radial-gradient(ellipse 75% 180px at 50% 0%, rgba(163, 40, 72, 0.16) 0%, rgba(218, 118, 148, 0.05) 55%, transparent 100%),
    linear-gradient(180deg, rgba(26, 10, 18, 1) 0%, rgba(34, 13, 23, 0.88) 100%) !important;
  background-size: 100% 220px, 100% 100% !important;
  background-repeat: no-repeat !important;
  box-shadow: 0 14px 28px -6px var(--shadow-c) !important;
  z-index: 3005 !important;
}

#top-settings-holder {
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  width: var(--sheldWidth) !important;
  max-width: 100% !important;
  margin: 0 auto !important;
  height: var(--topBarBlockSize) !important;
  padding: 0 var(--sp-2);
  align-items: center;
  box-shadow: none;
}

.drawer {
  background-color: transparent;
  color: var(--c-text);
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* 彻底移除图标底部的圆形/胶囊背景示意，全状态全透明 */
.drawer-toggle,
.drawer-toggle:hover,
.drawer-toggle:active,
.drawer-toggle:has(.openIcon) {
  padding: 0 !important;
  border-radius: 0 !important;
  background: transparent !important;
  background-color: transparent !important;
  background-image: none !important;
  box-shadow: none !important;
  border: none !important;
}

.drawer-icon {
  width: auto !important;
  padding: calc((var(--topBarBlockSize) - 8px - var(--icon-size) * 1.12) / 2) var(--sp-3) !important;
  font-size: calc(var(--icon-size) * 1.12) !important;
  border-radius: 0 !important;
  background: transparent !important;
  background-color: transparent !important;
  box-shadow: none !important;
  text-shadow: none !important;
  transition:
    opacity 220ms var(--tgEase),
    color 220ms var(--tgEase),
    filter 220ms var(--tgEase),
    transform var(--motion-release) var(--motion-ease-release) !important;
}

.drawer-icon.closedIcon {
  opacity: 0.42;
  color: rgba(246, 238, 242, 0.85) !important;
  filter: none;
}

.drawer-toggle:hover .drawer-icon.closedIcon,
.drawer-icon.closedIcon:hover {
  opacity: 0.86;
  color: #ffffff !important;
  filter: drop-shadow(0 0 6px rgba(255, 232, 240, 0.30));
}

.drawer-toggle:active .drawer-icon,
.drawer-icon:active {
  transform: scale(0.92) !important;
  transition-duration: var(--motion-press) !important;
}

.drawer-icon.openIcon {
  opacity: 1 !important;
  background: transparent !important;
  -webkit-background-clip: border-box !important;
  background-clip: border-box !important;
  color: #fff7fa !important;
  filter:
    drop-shadow(0 0 5px rgba(255, 240, 246, 0.62))
    drop-shadow(0 0 12px rgba(var(--sc-rose-rgb), 0.72));
}

.right_menu_button {
  opacity: 0.52;
  transition: opacity var(--dur-1) var(--tgEase);
}

.right_menu_button:hover {
  opacity: 0.95;
}

/* ---------- 4.2 悬浮抽屉与左右侧栏 ---------- */
.drawer-content {
  padding: var(--sp-5) !important;
  border-radius: var(--r-xl) !important;
  overflow-y: hidden;
}

.drawer-content:not(.fillLeft):not(.fillRight) {
  position: absolute;
  top: calc(var(--topBarBlockSize) + var(--ft-gap)) !important;
  max-height: calc(100dvh - var(--topBarBlockSize) - var(--ft-gap) * 3) !important;
  overflow-y: auto !important;
  scrollbar-gutter: stable;
}

.drawer-content.closedDrawer {
  display: none !important;
  pointer-events: none !important;
  visibility: hidden !important;
}

.drawer-content.closedDrawer:not(.fillLeft):not(.fillRight) {
  height: 0 !important;
  opacity: 1 !important;
  transform: none !important;
}

.drawer-content.openDrawer:not(.fillLeft):not(.fillRight) {
  display: block !important;
  height: auto !important;
  opacity: 1 !important;
  transform: none !important;
  pointer-events: auto !important;
  visibility: visible !important;
  overflow-y: auto !important;
}

#top-settings-holder .drawer-content:not(.fillLeft):not(.fillRight),
body:not(.movingUI) #top-settings-holder .drawer-content.maximized:not(.fillLeft):not(.fillRight) {
  top: calc(var(--topBarBlockSize) + var(--ft-gap)) !important;
  max-height: calc(100dvh - var(--topBarBlockSize) - var(--ft-gap) * 3) !important;
}

#top-settings-holder #WorldInfo {
  top: calc(var(--topBarBlockSize) + var(--ft-gap) * 2) !important;
  max-height: calc(100dvh - var(--topBarBlockSize) - var(--ft-gap) * 3) !important;
}

#left-nav-panel,
#right-nav-panel {
  top: var(--ft-gap) !important;
  height: calc(100dvh - var(--ft-gap) * 2) !important;
  max-height: calc(100dvh - var(--ft-gap) * 2) !important;
  width: calc((100dvw - var(--sheldWidth)) / 2 - var(--ft-gap) * 2) !important;
  border-radius: var(--r-xl) !important;
  padding: var(--sp-5) var(--sp-4) var(--sp-5) var(--sp-5) !important;
}

#left-nav-panel {
  left: var(--ft-gap) !important;
}

#right-nav-panel {
  left: auto !important;
  right: var(--ft-gap) !important;
}

#clickSlidersTips,
#left-nav-panel .topRightInset {
  top: var(--sp-3);
}

/* ---------- 4.3 悬浮聊天主舞台 (#sheld / #chat) 与防遮挡弹性底栏 (#form_sheld / #send_form) ----------
   彻底根治手机/移动端输入框遮挡对话的恶性问题：
   1. #sheld 设为真正的 Flex 垂直列容器，容纳 #chat 与 #form_sheld，以 gap: var(--ft-gap) 物理分隔；
   2. #chat 设置 flex: 1 1 0px !important; min-height: 0 !important; 自身独立内滚，高度自动收缩；
   3. #form_sheld 恢复为流式容器 (position: relative !important; flex: 0 0 auto !important;)，
      高度由 #send_form 内容自适应撑开（无论是单行、多行还是按钮折行），永远物理位于 #chat 正下方，
      彻底消灭 absolute 悬浮覆盖，无论移动端虚拟键盘弹出还是快捷栏折行，最后一条对话永远 100% 完整可见！ */
#sheld {
  top: calc(var(--topBarBlockSize) + var(--ft-gap));
  height: calc(100dvh - var(--topBarBlockSize) - var(--ft-gap) * 2 - var(--sc-nav-bottom, 0px));
  max-height: calc(100dvh - var(--topBarBlockSize) - var(--ft-gap) * 2 - var(--sc-nav-bottom, 0px));
  display: flex !important;
  flex-direction: column !important;
  gap: var(--ft-gap) !important;
  overflow: visible !important;
}

#chat {
  flex: 1 1 0px !important;
  min-height: 0 !important;
  height: auto !important;
  max-height: none !important;
  overflow-y: auto !important;
  align-items: center;
  padding: var(--sp-4) var(--sp-4) var(--sp-3) var(--sp-4) !important;
  border-radius: var(--r-xl);
  background-color: var(--glass-chat);
  background-image: var(--vol-panel-wash);
  background-size: 100% 220px, 100% 140px;
  background-repeat: no-repeat;
  box-shadow: var(--elev-2);
  letter-spacing: var(--ft-letter-spacing);
  scroll-padding-bottom: var(--sp-3);
}

/* 触屏端保持清晰的磨砂层，同时提高酒红底色，避免背景透得发空。 */
@media (hover: none) {
  body:not(.no-blur) #chat {
    -webkit-backdrop-filter: blur(16px) saturate(1.2) !important;
    backdrop-filter: blur(16px) saturate(1.2) !important;
    background-color: rgb(from var(--SmartThemeChatTintColor) r g b / var(--ftu-chat-alpha, max(0.44, alpha))) !important;
  }
}

#chat::-webkit-scrollbar-track {
  margin: var(--sp-3) 0 var(--sp-3) 0;
}

/* 悬浮输入岛：弹性流式定位，零遮挡对话，24px 圆角与柔和景深阴影 */
#form_sheld {
  position: relative !important;
  flex: 0 0 auto !important;
  width: 100% !important;
  left: 0 !important;
  right: 0 !important;
  bottom: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  z-index: 31;
}

#send_form,
body.no-blur #send_form {
  min-height: calc(var(--bottomFormBlockSize) + var(--sp-3));
  padding: var(--sp-2) var(--sp-3) !important;
  border-radius: var(--r-lg) !important;
  background-color: var(--glass-float) !important;
  background-image: var(--vol-panel-wash) !important;
  box-shadow: var(--elev-3) !important;
  outline: none !important;
  box-sizing: border-box !important;
}

#send_form textarea,
#send_textarea {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  border-radius: var(--r-sm) !important;
  color: var(--c-text) !important;
  line-height: 1.6;
  resize: none !important;
  padding: max(6px, calc((var(--bottomFormBlockSize) + 2px - 1.6em) / 2)) var(--sp-3) !important;
}

#send_form textarea::placeholder {
  color: var(--c-text-3) !important;
}

#leftSendForm > div,
#rightSendForm > div:not(.mes_stop):not(#send_but) {
  width: var(--bottomFormBlockSize) !important;
  height: var(--bottomFormBlockSize) !important;
  aspect-ratio: 1;
  flex: none;
  border-radius: 50%;
  font-size: calc(var(--icon-size) * 1.15);
  opacity: 0.65;
  transition: background-color var(--dur-1) var(--tgEase), opacity var(--dur-1) var(--tgEase), transform var(--motion-release) var(--motion-ease-release) !important;
}

#leftSendForm > div:hover,
#rightSendForm > div:not(.mes_stop):not(#send_but):hover {
  opacity: 1;
  background-color: rgba(255, 232, 240, 0.08) !important;
  background-image: radial-gradient(circle, rgba(255, 232, 240, 0.12) 0%, transparent 75%) !important;
  filter: brightness(1.15) !important;
}

#leftSendForm > div:active,
#rightSendForm > div:active {
  transform: scale(0.92) !important;
  transition-duration: var(--motion-press) !important;
}

#send_but {
  border-radius: 50% !important;
  background: var(--gradient-main) !important;
  color: #fff !important;
  opacity: 1 !important;
  font-size: calc(var(--icon-size) * 1.02) !important;
  transform: scale(0.86);
  box-shadow: 0 4px 14px rgba(var(--sc-accent-rgb), 0.42);
  transition: transform var(--motion-release) var(--motion-ease-release), box-shadow var(--dur-2) var(--tgEase), filter var(--dur-1) var(--tgEase) !important;
}

#send_but:hover {
  transform: scale(0.86);
  box-shadow: 0 6px 20px rgba(var(--sc-accent-rgb), 0.58);
  filter: brightness(1.08) !important;
}

#send_but:active {
  transform: scale(0.81) !important;
  transition-duration: var(--motion-press) !important;
}

#mes_stop {
  color: var(--c-danger);
}

/* ==========================================================================
   5. 消息卡片（中心醇厚、向四周边缘柔和羽化消散 + 零发光内框）
   ========================================================================== */

.mes,
body.bubblechat .mes {
  width: 100%;
  margin: 0 0 var(--sp-3) 0 !important;
  padding: var(--sp-4) var(--ft-mes-pad) var(--sp-4) var(--ft-mes-pad) !important;
  border: none !important;
  border-radius: var(--r-lg) !important;
  background-color: transparent !important;
  background-image: var(--vol-card-bot-bg) !important;
  box-shadow: var(--vol-card-shadow) !important;
}

.mes[is_user="true"],
body.bubblechat .mes[is_user="true"] {
  background-color: transparent !important;
  background-image: var(--vol-card-user-bg) !important;
  box-shadow: var(--vol-card-shadow) !important;
}

#chat .mes.selected {
  background-image: radial-gradient(ellipse at 50% 50%, rgba(224, 82, 96, 0.34) 0%, rgba(224, 82, 96, 0.16) 100%) !important;
}

/* 头像：柔和阴影，无硬框 */
.avatar img,
body.big-avatars .avatar img {
  border: none !important;
}

.mes[is_user="true"] .avatar img {
  box-shadow: 0 4px 14px rgba(var(--sc-accent-rgb), 0.34);
}

.mes[is_user="false"] .avatar img {
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.32);
}

.avatar.interactable {
  transition: filter var(--dur-1) var(--tgEase), transform var(--motion-release) var(--motion-ease-release) !important;
}

.avatar.interactable:hover {
  filter: brightness(1.06);
}

.avatar.interactable:active {
  transform: scale(0.95);
}

.mesIDDisplay,
.mes_timer,
.tokenCounterDisplay,
.mes .mes_date,
.timestamp {
  color: var(--c-text-3);
  font-size: var(--fs-xs);
  opacity: 0.82;
  font-variant-numeric: tabular-nums;
}

.mes_block {
  overflow: visible !important;
  clip-path: inset(-28px 0 -28px 0);
}

/* 角色名与柔和渐变雾带 */
#chat .ch_name {
  position: relative;
  align-items: center;
  padding: var(--sp-1) 0 var(--sp-2) 0;
}

#chat .ch_name::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(90deg, rgba(var(--sc-rose-rgb), 0.28) 0%, rgba(var(--sc-accent-rgb), 0.08) 50%, transparent 100%);
  border-radius: 9999px;
  pointer-events: none;
}

.name_text {
  font-size: var(--fs-md);
  font-weight: 600;
  letter-spacing: 0.01em;
}

.mes_text {
  line-height: var(--lh-body);
}

.last_mes .mes_text {
  padding-right: 0;
}

.mes_text p,
.mes_reasoning p {
  margin: 0 0 var(--ft-para-gap) 0;
}

.mes_text p:last-child,
.mes_reasoning p:last-child {
  margin-bottom: 0;
}

/* 消息操作按钮：纯图标高亮过渡，无背景框 */
.mes_buttons .mes_button,
.extraMesButtons .mes_button,
.mes_edit,
.mes_buttons > div,
.extraMesButtons > div {
  padding: var(--sp-1) var(--sp-2) !important;
  border-radius: var(--r-xs);
  filter: none !important;
  transition: opacity var(--dur-1) var(--tgEase), transform var(--motion-release) var(--motion-ease-release), color var(--dur-1) var(--tgEase) !important;
}

.mes_buttons .mes_button {
  opacity: 0;
}

.mes:hover .mes_buttons .mes_button {
  opacity: 0.54;
}

.mes_buttons .mes_button:hover,
.extraMesButtons .mes_button:hover,
.mes_edit:hover {
  opacity: 1 !important;
  color: var(--c-2);
}

.mes_button:active,
.extraMesButtons > div:active,
.mes_edit_done:active,
.mes_edit_cancel:active {
  transform: scale(0.92) !important;
}

.mes[is_user="false"].last_mes .mes_block {
  padding-bottom: 32px;
}

.swipe_left,
.swipe_right {
  border-radius: 50%;
  transition: opacity var(--dur-1) var(--tgEase);
}

.swipeRightBlock {
  flex-direction: row-reverse;
  right: calc(var(--ft-mes-pad) - 6px);
  bottom: var(--sp-2);
}

.last_mes .swipeRightBlock {
  margin: 0;
}

.swipes-counter {
  margin-bottom: 0;
  color: var(--c-text-3);
  font-variant-numeric: tabular-nums;
}

/* ---------- 5.1 思考 / 推理块 (.mes_reasoning)：中心实、四周渐隐 ---------- */
.mes_reasoning_details {
  margin-top: var(--sp-2);
}

.mes_reasoning_header {
  margin: 0.5em 0;
  padding: var(--sp-2) calc(var(--mainFontSize) + var(--sp-4)) var(--sp-2) var(--sp-3);
  border-radius: var(--r-md);
  border: none !important;
  background-color: transparent;
  background-image:
    radial-gradient(ellipse 120% 115% at 50% 50%, rgba(var(--sc-accent-rgb), 0.24) 0%, rgba(var(--sc-accent-rgb), 0.14) 65%, rgba(var(--sc-accent-rgb), 0.05) 100%);
  box-shadow: var(--vol-ctl-shadow);
  color: var(--c-text);
  filter: brightness(1) !important;
  transition:
    filter var(--dur-1) var(--tgEase),
    background-color var(--dur-1) var(--tgEase),
    box-shadow var(--dur-1) var(--tgEase) !important;
}

.mes_reasoning_header:hover {
  background-color: rgba(255, 235, 243, 0.05) !important;
  background-image:
    radial-gradient(ellipse 120% 115% at 50% 50%, rgba(var(--sc-accent-rgb), 0.32) 0%, rgba(var(--sc-accent-rgb), 0.18) 65%, rgba(var(--sc-accent-rgb), 0.07) 100%) !important;
  filter: brightness(1.07) !important;
}

.mes_reasoning_header span::before {
  content: "✦";
  position: relative;
  font-size: var(--fs-md);
  line-height: 1;
  margin-right: 6px;
  color: var(--c-2);
}

.mes_reasoning_details .mes_reasoning_arrow {
  right: var(--sp-3);
  font-size: calc(var(--mainFontSize) * 0.72) !important;
}

.mes_reasoning {
  margin-top: var(--sp-1);
  padding: var(--sp-2) var(--sp-3);
  border: none !important;
  border-radius: var(--r-md);
  background-image: var(--vol-recess-bg);
  box-shadow: var(--vol-recess-shadow);
  line-height: 1.75;
  color: color-mix(in srgb, var(--c-text) 88%, transparent);
}

/* ---------- 5.2 引用块、表格、正文折叠块与分割线（无边框中心渐隐） ---------- */
blockquote,
.mes_text blockquote,
.mes_reasoning blockquote {
  margin: 0.85em 0;
  padding: var(--sp-3) var(--sp-4) !important;
  border: none !important;
  border-radius: var(--r-md) !important;
  background-color: transparent !important;
  background-image:
    radial-gradient(ellipse 120% 115% at 35% 50%, rgba(var(--sc-accent-rgb), 0.20) 0%, rgba(16, 6, 11, 0.28) 68%, rgba(12, 4, 8, 0.10) 100%) !important;
  box-shadow: var(--vol-ctl-shadow) !important;
  color: var(--c-text);
}

.mes_text table {
  border-collapse: separate;
  border-spacing: 0;
  margin: 0.85em 0;
  border: none !important;
  border-radius: var(--r-md);
  overflow: hidden;
  background-image: var(--vol-recess-bg);
  box-shadow: var(--vol-recess-shadow);
  line-height: var(--lh-ui);
}

.mes_text th,
.mes_text td {
  padding: var(--sp-2) var(--sp-3);
  border: none !important;
  text-align: left;
  transition: background-color var(--dur-1) var(--tgEase);
}

