/* ---------- 8.2 滑动条（普通控件与 .neo-range-slider 分离规格） ----------
   普通控件保留酒红渐变轨道；.neo-range-slider 对齐 SillyClient：
   2px 深灰纤细轨道 + 12×12px 暗沉灰蓝圆润拨杆。 */
.range-block {
  margin: var(--sp-3) 0;
  gap: 4px;
}

.range-block-title {
  text-align: left;
  margin-bottom: var(--sp-1);
  line-height: var(--lh-ui);
}

.range-block-counter {
  margin-left: var(--sp-4);
  font-variant-numeric: tabular-nums;
}

.range-block-range-and-counter {
  gap: var(--sp-3);
  align-items: center;
}

input[type="range"],
#talkativeness_div input[type="range"] {
  -webkit-appearance: none !important;
  appearance: none !important;
  height: 14px !important;
  padding: 0 !important;
  border: none !important;
  border-radius: 0 !important;
  background: transparent !important;
  background-color: transparent !important;
  background-image: none !important;
  background-size: 100% 100% !important;
  box-shadow: none !important;
  outline: none;
  filter: none !important;
  cursor: pointer !important;
}

input[type="range"]:not(.neo-range-slider)::-webkit-slider-runnable-track,
#talkativeness_div input[type="range"]::-webkit-slider-runnable-track {
  height: 5px !important;
  border-radius: 999px !important;
  background: rgba(255, 230, 240, 0.22) !important;
  border: none !important;
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.45) !important;
}

input[type="range"].neo-range-slider::-webkit-slider-runnable-track {
  height: 2px !important;
  border-radius: 1px !important;
  background: oklch(0.5 0 0 / 0.12) !important;
  border: none !important;
  box-shadow: none !important;
}

input[type="range"]:not(.neo-range-slider)::-webkit-slider-thumb,
#talkativeness_div input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none !important;
  appearance: none !important;
  width: 16px !important;
  height: 16px !important;
  border-radius: 50% !important;
  border: none !important;
  background: radial-gradient(circle at 35% 35%, #ffffff 0%, rgb(var(--sc-rose-rgb)) 65%, rgb(var(--sc-accent-rgb)) 100%) !important;
  margin-top: -5.5px !important; /* (5px track - 16px thumb) / 2 = -5.5px: 数学绝对垂直居中 */
  box-shadow:
    0 1.5px 5px rgba(0, 0, 0, 0.45),
    0 0 10px rgba(var(--sc-rose-rgb), 0.55) !important;
  cursor: pointer !important;
  transition: transform var(--dur-1) var(--tgEase), filter var(--dur-1) var(--tgEase) !important;
}

input[type="range"].neo-range-slider::-webkit-slider-thumb {
  -webkit-appearance: none !important;
  appearance: none !important;
  width: 12px !important;
  height: 12px !important;
  margin-top: -5px !important;
  border-radius: 50% !important;
  border: none !important;
  background: oklch(0.45 0.015 250) !important;
  box-shadow:
    0 0.5px 2px oklch(0 0 0 / 0.25),
    inset 0 0.5px 0 oklch(1 0 0 / 0.15) !important;
  cursor: pointer !important;
}

input[type="range"]:not(.neo-range-slider):hover::-webkit-slider-thumb {
  filter: brightness(1.15) !important;
}

input[type="range"]:not(.neo-range-slider)::-moz-range-track,
#talkativeness_div input[type="range"]::-moz-range-track {
  height: 5px !important;
  border-radius: 999px !important;
  background: rgba(255, 230, 240, 0.22) !important;
  border: none !important;
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.45) !important;
}

input[type="range"]:not(.neo-range-slider)::-moz-range-thumb,
#talkativeness_div input[type="range"]::-moz-range-thumb {
  width: 16px !important;
  height: 16px !important;
  border-radius: 50% !important;
  border: none !important;
  background: radial-gradient(circle at 35% 35%, #ffffff 0%, rgb(var(--sc-rose-rgb)) 65%, rgb(var(--sc-accent-rgb)) 100%) !important;
  box-shadow:
    0 1.5px 5px rgba(0, 0, 0, 0.45),
    0 0 10px rgba(var(--sc-rose-rgb), 0.55) !important;
  cursor: pointer !important;
}

input[type="range"].neo-range-slider::-moz-range-track {
  height: 2px !important;
  border-radius: 1px !important;
  background: oklch(0.5 0 0 / 0.15) !important;
  border: none !important;
  box-shadow: none !important;
}

input[type="range"].neo-range-slider::-moz-range-thumb {
  width: 12px !important;
  height: 12px !important;
  border-radius: 50% !important;
  border: none !important;
  background: oklch(0.45 0.015 250) !important;
  box-shadow:
    0 0.5px 2px oklch(0 0 0 / 0.25),
    inset 0 0.5px 0 oklch(1 0 0 / 0.15) !important;
  cursor: pointer !important;
}

input[type="range"].neo-range-slider:hover::-webkit-slider-thumb {
  background: oklch(0.52 0.018 250) !important;
  box-shadow:
    0 0.5px 2.5px oklch(0 0 0 / 0.3),
    inset 0 0.5px 0 oklch(1 0 0 / 0.22) !important;
}

input[type="range"].neo-range-slider:active::-webkit-slider-thumb {
  background: oklch(0.56 0.02 250) !important;
  transform: scale(0.94);
}

input[type="range"]:disabled,
.disabled input[type="range"] {
  opacity: 0.36 !important;
  filter: saturate(0.2) !important;
  cursor: not-allowed !important;
}

.neo-range-slider {
  width: 100% !important;
  margin: var(--sp-2) 0 !important;
}

.neo-range-input {
  min-height: var(--ft-ctl-h);
  margin-top: var(--sp-1);
