/* ==========================================================================
   开屏与全局启动加载层深度加固 (#preloader / #loader.splash-screen)
   - 杜绝启动色温骤变：#preloader 铺设与主题一致的波尔多暗红辐射渐变与丝滑高斯模糊；
   - 彻底根除开屏 CLS 跳动：为 .splash-logo 强制显式宽高与 aspect-ratio，初始帧立即占位；
   - 品牌专属微动效：Logo 玫瑰呼吸光晕，无突兀跳弹；
   - 齿轮光学校准：修正 load-spinner 容器溢出晃动，赋予珍珠玫瑰高亮微辉光；
   - 优雅排版：.splash-message 字距微调与柔光阴影，消除粗糙浏览器默认字重。
   ========================================================================== */
#preloader {
  position: fixed !important;
  top: 0 !important;
  left: 0 !important;
  width: 100vw !important;
  width: 100dvw !important;
  height: 100vh !important;
  height: 100dvh !important;
  z-index: 999999 !important;
  background-color: #12050c !important;
  background-image: radial-gradient(ellipse 80% 60% at 50% 40%, rgba(68, 20, 42, 0.42) 0%, rgba(18, 6, 13, 0.98) 78%) !important;
  backdrop-filter: blur(24px) saturate(130%) !important;
  -webkit-backdrop-filter: blur(24px) saturate(130%) !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  margin: 0 !important;
  padding: 0 !important;
  opacity: 1 !important;
  pointer-events: none !important;
}

#loader.splash-screen {
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  justify-content: center !important;
  gap: var(--sp-4, 1.5rem) !important;
  width: 100% !important;
  height: 100% !important;
  user-select: none !important;
  contain: layout style !important;
  box-sizing: border-box !important;
}

.splash-logo {
  width: min(136px, 36vw) !important;
  height: min(136px, 36vw) !important;
  min-width: 90px !important;
  min-height: 90px !important;
  aspect-ratio: 1 / 1 !important;
  object-fit: contain !important;
  filter: drop-shadow(0 10px 28px rgba(0, 0, 0, 0.55)) drop-shadow(0 0 20px rgba(226, 75, 122, 0.35)) !important;
