}

#toast-container.toast-top-right,
#toast-container.toast-bottom-right {
  align-items: flex-end !important;
}

/* SillyTavern moves the same container into an open dialog so it can sit
   above modal content. Keep the dialog-specific offsets instead of applying
   the body-wide dock geometry there. */
.popup #toast-container {
  left: auto !important;
  right: auto !important;
  width: auto !important;
  padding: 0 !important;
}

.popup #toast-container.toast-top-left {
