  left: var(--toast-edge, 12px) !important;
  right: auto !important;
  align-items: flex-start !important;
}

.popup #toast-container.toast-top-center {
  top: var(--topBarBlockSize) !important;
  left: 0 !important;
  right: 0 !important;
  width: 100% !important;
  align-items: center !important;
  padding: 0 var(--ft-gap) !important;
}

.popup #toast-container.toast-top-right {
  top: calc(var(--toast-edge, 12px) + var(--topBarBlockSize)) !important;
  left: auto !important;
  right: var(--toast-edge, 12px) !important;
  align-items: flex-end !important;
}

.popup #toast-container.toast-bottom-left {
  top: auto !important;
  left: var(--toast-edge, 12px) !important;
  right: auto !important;
  bottom: var(--toast-edge, 12px) !important;
  align-items: flex-start !important;
}

.popup #toast-container.toast-bottom-center {
  top: auto !important;
  left: 0 !important;
  right: 0 !important;
  bottom: 0 !important;
  width: 100% !important;
  align-items: center !important;
  padding: 0 var(--ft-gap) !important;
}

.popup #toast-container.toast-bottom-right {
  top: auto !important;
  left: auto !important;
  right: var(--toast-edge, 12px) !important;
  bottom: var(--toast-edge, 12px) !important;
  align-items: flex-end !important;
}

body #toast-container > div[class] {
  --toast-accent: var(--c-2);
  position: relative !important;
  box-sizing: border-box !important;
  width: min(420px, calc(100dvw - var(--ft-gap) * 2)) !important;
  max-width: 100% !important;
  margin: 0 0 var(--sp-2) 0 !important;
  padding: var(--sp-3) var(--sp-5) var(--sp-3) 64px;
  border-radius: var(--r-lg) !important;
  border: none !important;
  border-left: 3.5px solid var(--toast-accent) !important;
  background-color: var(--glass-top) !important;
  background-image: var(--vol-panel-wash) !important;
  background-size: 100% 220px, 100% 140px !important;
  background-repeat: no-repeat !important;
  color: var(--c-text) !important;
  font-size: var(--fs-sm);
  line-height: var(--lh-ui);
  opacity: 1;
  overflow: visible !important;
  box-shadow:
    0 0 16px -2px color-mix(in srgb, var(--toast-accent) 22%, transparent),
    var(--elev-4) !important;
  animation-name: sc-toast-enter;
  animation-duration: 160ms;
  animation-timing-function: var(--scFastOut);
  animation-fill-mode: none;
  pointer-events: auto !important;
}

#toast-container.toast-top-center > div[class],
#toast-container.toast-bottom-center > div[class] {
  margin-left: auto !important;
  margin-right: auto !important;
}

body #toast-container > div.toast-error {
  --toast-accent: var(--c-danger);
}

body #toast-container > div.toast-success {
  --toast-accent: var(--c-success);
}

body #toast-container > div.toast-warning {
  --toast-accent: var(--c-warning);
}

body #toast-container > div.toast-info {
  --toast-accent: var(--c-2);
}

body #toast-container > div::before {
  content: "\f05a";
  position: absolute;
  left: 18px;
  top: 50%;
  transform: translateY(-50%);
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  font-family: "Font Awesome 6 Free" !important;
  font-weight: 900 !important;
  font-size: 13.5px;
  color: var(--toast-accent);
  background: radial-gradient(circle, color-mix(in srgb, var(--toast-accent) 28%, transparent) 0%, color-mix(in srgb, var(--toast-accent) 8%, transparent) 80%, transparent 100%);
  box-shadow:
    0 0 14px 2px color-mix(in srgb, var(--toast-accent) 55%, transparent),
    0 0 24px 6px color-mix(in srgb, var(--toast-accent) 25%, transparent);
}

body #toast-container .toast-error::before {
  content: "\f06a";
}

body #toast-container .toast-success::before {
  content: "\f058";
}

body #toast-container .toast-warning::before {
  content: "\f071";
}

.toast-title {
  color: var(--toast-accent);
  font-size: var(--fs-sm);
  margin-bottom: 2px;
}

body #toast-container .toast-message {
  display: -webkit-box;
