  box-shadow: 0 0 10px rgba(var(--sc-accent-rgb), 0.22), var(--vol-ctl-shadow) !important;
}

/* ==========================================================================
   10. 零重排物理动效体系与移动端/窄屏全适配
   ========================================================================== */

@keyframes pop-in {
  0% {
    opacity: 0;
    transform: scale(0.982) translate3d(0, 6px, 0);
  }
  100% {
    opacity: 1;
    transform: scale(1) translate3d(0, 0, 0);
  }
}

@keyframes tg-menu-in {
  from {
    opacity: 0;
    transform: translate3d(0, -4px, 0) scale(0.988);
  }
  to {
    opacity: 1;
    transform: translate3d(0, 0, 0) scale(1);
  }
}

@keyframes sc-mes-in {
  from {
    opacity: 0;
    transform: translate3d(0, 6px, 0);
  }
  to {
    opacity: 1;
    transform: none;
  }
}


.popup:not(.popup--animation-fast):not(.popup--animation-slow):not(.popup--animation-none) {
  --popup-animation-speed: 160ms;
}

.popup[opening]:not(.popup--animation-none):not(.transparent_dialogue_popup) {
  animation: pop-in var(--popup-animation-speed) var(--scFastOut) !important;
}

#options .options-content,
#extensionsMenu,
.list-group,
.select2-dropdown {
  animation: tg-menu-in 120ms var(--scFastOut) backwards;
}

#chat .mes.last_mes {
  animation: sc-mes-in 180ms var(--tgSpring) backwards;
}

/* 触屏设备专属优化：收敛饱和度，动画仅保留 GPU 合成属性 (transform/opacity) */
@media (hover: none) {
  :root {
    --ft-saturate: var(--ftu-saturate, 126%);
  }

  .mes_buttons .mes_button {
    opacity: 0.36;
  }

  .menu_button,
  .menu_button:not(.disabled):not([disabled]):hover,
  .menu_button:not(.disabled):not([disabled]):active,
  .list-group-item,
  .options-content a,
  #extensionsMenu > div,
  .character_select,
  .tag,
  .select2-results .select2-results__option--selectable {
    transition-property: transform, opacity !important;
  }

  .popup[opening]:not(.transparent_dialogue_popup),
  .popup[closing]:not(.transparent_dialogue_popup) {
    background-color: rgba(var(--sc-solid-rgb), 0.97) !important;
  }
}

/* 手机与窄屏视口（<= 1000px）：视口宽顶栏、防遮挡弹性底栏、视口定位抽屉与自适应滑块 */
@media screen and (max-width: 1000px) {
  :root {
    --ft-gap: calc(var(--ftu-gap, 10px) * 0.7);
    --ft-mes-pad: calc(var(--ftu-mes-pad, 22px) * 0.72);
  }

  /* Narrow layouts use the viewport width; --sheldWidth may still hold a desktop-only value. */
  #top-bar,
  body.no-blur #top-bar,
  #top-settings-holder {
    box-sizing: border-box !important;
    width: 100dvw !important;
    max-width: 100dvw !important;
    left: 0 !important;
    right: 0 !important;
    margin: 0 auto !important;
  }

  #top-bar {
    top: 0 !important;
    border-radius: 0 0 var(--r-topbar) var(--r-topbar) !important;
  }

  #top-settings-holder {
    position: fixed !important;
    top: 0 !important;
  }

  .drawer-icon {
    padding-left: var(--sp-1) !important;
    padding-right: var(--sp-1) !important;
    font-size: 16px !important;
  }

  #clickSlidersTips {
    position: static;
    width: 100%;
    margin: 0 0 var(--sp-2) 0;
    padding-right: var(--sp-6);
  }

  #user-settings-block div[name="userSettingsRowOne"] {
    flex-wrap: wrap;
    row-gap: var(--sp-2);
  }

  #UI-language-block {
    order: 3;
    flex: 1 1 100%;
  }

  #UI-language-block > select {
    flex: 1 1 auto;
  }

  #world_editor_select {
    flex: 1 1 55%;
    min-width: 55%;
  }

  #sheld {
    width: calc(100dvw - var(--ft-gap) * 2) !important;
    left: var(--ft-gap) !important;
    right: var(--ft-gap) !important;
    margin: 0 auto !important;
    top: calc(var(--topBarBlockSize) + var(--ft-gap)) !important;
    height: calc(100dvh - var(--topBarBlockSize) - var(--ft-gap) * 2 - var(--sc-nav-bottom, 0px)) !important;
    max-height: calc(100dvh - var(--topBarBlockSize) - var(--ft-gap) * 2 - var(--sc-nav-bottom, 0px)) !important;
    display: flex !important;
    flex-direction: column !important;
    gap: var(--ft-gap) !important;
    overflow: visible !important;
  }

  /* Flex 岛屿已经让输入区回到文档流，只保留横向内边距和滚动槽位 */
  #chat {
    border: none;
    border-radius: var(--r-lg) !important;
    padding-left: var(--sp-2) !important;
    padding-right: var(--sp-2) !important;
    scroll-padding-bottom: var(--sp-3) !important;
  }

  #form_sheld {
    position: relative !important;
    flex: 0 0 auto !important;
    width: 100% !important;
    left: 0 !important;
    right: 0 !important;
    bottom: 0 !important;
    margin: 0 !important;
    z-index: 31 !important;
  }

  .mes_block {
    clip-path: inset(-28px -20px -28px -20px) !important;
  }

  .drawer-content {
    padding: var(--sp-3) !important;
  }

  /* 抽屉在手机端居中撑满可用宽度，左右对称留白，彻底解决抽屉偏右、左侧露黑背景恶性问题 */
  #top-settings-holder .drawer-content:not(.fillLeft):not(.fillRight),
  .drawer-content:not(.fillLeft):not(.fillRight),
  #character_popup {
    width: calc(100dvw - var(--ft-gap) * 2) !important;
    max-width: calc(100dvw - var(--ft-gap) * 2) !important;
    left: var(--ft-gap) !important;
    right: var(--ft-gap) !important;
    margin: 0 auto !important;
    top: calc(var(--topBarBlockSize) + var(--ft-gap)) !important;
    max-height: calc(100dvh - var(--topBarBlockSize) - var(--ft-gap) * 2) !important;
    z-index: 3000 !important;
  }

  #top-settings-holder .drawer-content:not(.fillLeft):not(.fillRight) {
    position: fixed !important;
  }

  #left-nav-panel,
  #right-nav-panel {
    top: calc(var(--topBarBlockSize) + var(--ft-gap) * 2) !important;
    left: var(--ft-gap) !important;
    right: var(--ft-gap) !important;
    width: calc(100dvw - var(--ft-gap) * 2) !important;
    min-width: 0 !important;
    max-width: calc(100dvw - var(--ft-gap) * 2) !important;
    height: calc(100dvh - var(--topBarBlockSize) - var(--ft-gap) * 3) !important;
    max-height: calc(100dvh - var(--topBarBlockSize) - var(--ft-gap) * 3) !important;
    padding: var(--sp-3) !important;
  }

  /* 酒馆原生在 <=1000px 隐藏弹出触发器，移动端仍保留可用入口 */
  #qr--bar > #qr--popoutTrigger {
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    flex: 0 0 28px !important;
    width: 28px !important;
    height: 28px !important;
    opacity: 0.85 !important;
  }

  #qr--popout {
    box-sizing: border-box !important;
    display: flex !important;
    position: fixed;
    top: auto;
    left: auto;
    right: var(--ft-gap);
    bottom: calc(var(--bottomFormBlockSize, 60px) + var(--sc-nav-bottom, 14px) + 10px);
    width: min(360px, calc(100dvw - var(--ft-gap) * 2));
    max-width: calc(100dvw - var(--ft-gap) * 2) !important;
    height: auto;
    min-height: 0 !important;
    min-width: 0 !important;
    max-height: 60vh !important;
    overflow-y: auto !important;
    z-index: 2147483000 !important;
  }

  #select_chat_popup {
    width: calc(100dvw - var(--ft-gap) * 2) !important;
    max-width: calc(100dvw - var(--ft-gap) * 2) !important;
    padding: var(--sp-2) !important;
  }

  .select_chat_actions,
  .renameChatButton {
    opacity: 0.9 !important;
  }
}

/* 窄屏手机管理聊天文件紧凑无遮挡布局（<= 600px） */
@media screen and (max-width: 600px) {
  .bg-drawer-layout .bg_list {
    box-sizing: border-box !important;
    width: 100% !important;
    max-width: 100% !important;
    grid-template-columns: repeat(auto-fill, minmax(145px, 1fr)) !important;
  }

  #chat .mes.smallSysMes .mes_text .drawer-opener.menu_button,
  .welcomePanel .drawer-opener.menu_button {
    margin: 4px 2px !important;
    padding: 8px !important;
    gap: 6px !important;
  }

  #select_chat_name_wrapper {
    gap: 4px !important;
  }

  #select_chat_name_wrapper > div:first-child {
    max-width: calc(100% - 142px) !important;
  }

  #select_chat_name_wrapper > div:last-child {
    max-width: 140px !important;
    gap: 4px !important;
  }

  .select_chat_info {
    max-width: 65px !important;
    gap: 2px !important;
    font-size: 10.5px !important;
  }

  .select_chat_actions {
    max-width: 70px !important;
    gap: 4px !important;
    opacity: 1 !important;
  }

  .select_chat_actions .PastChat_cross {
    min-width: 22px !important;
    min-height: 22px !important;
    opacity: 1 !important;
  }
}

/* 减少动态效果无障碍降级 */
body.reduced-motion #chat .mes.last_mes,
body.reduced-motion #toast-container > div,
body.reduced-motion .popup[opening],
body.reduced-motion .popup[closing],
body.reduced-motion #options .options-content,
body.reduced-motion #extensionsMenu,
body.reduced-motion .list-group,
body.reduced-motion .select2-dropdown,
body.reduced-motion .drawer-content.openDrawer,
body.reduced-motion .inline-drawer-content {
  animation: none !important;
}

@media (prefers-reduced-motion: reduce) {
  .menu_button,
  .list-group-item,
  .mes_button,
  .drawer-icon,
  .select2-results .select2-results__option--selectable,
  .character_select,
  .tag,
  .popup[opening],
  .popup[closing],
  #chat .mes.last_mes,
  #toast-container > div,
  #options .options-content,
  #extensionsMenu,
  .drawer-content.openDrawer,
  .inline-drawer-content {
    animation: none !important;
    transition: none !important;
  }
}

/* Mouse/touch focus must not add a decorative halo or bright outline. */
input:focus,
input:focus-visible,
textarea:focus,
textarea:focus-visible,
select:focus,
select:focus-visible {
  outline: none !important;
}

/* Keep the composer transparent while typing; other controls retain their
   static recessed surface from the base focus rule above. */
#send_form textarea:focus,
#send_textarea:focus {
  background-image: none !important;
  box-shadow: none !important;
  outline: none !important;
}
